from sys import stdin, setrecursionlimit
input = stdin.readline
setrecursionlimit(10 ** 6)

def dfs(p, prev, lvl):
	for i in child[p]:
		if i == prev:
			continue
		dfs(i, p, lvl + 1)
	if lvl & 1:
		a.append(abs(len(child[p]) - 2))

def answer():
	if q == 1:
		return sum(a)
	else:
		dp = 1
		for i in range(len(a)):
			dp |= dp << a[i]
		total = sum(a)
		ans = float('inf')
		for i in range(n + 1):
			if dp >> i & 1:
				ans = min(ans, abs(total - 2 * i))
		return ans
for T in range(int(input())):
	(n, q) = map(int, input().split())
	child = [[] for i in range(n + 1)]
	for i in range(n - 1):
		(u, v) = map(int, input().split())
		child[u].append(v)
		child[v].append(u)
	child[1].append(-1)
	a = []
	dfs(1, -1, 1)
	print(answer())
